// Normalises one Telegram update into the shape POST /api/ingest/message
// expects, and decides whether the message is addressed to the bot.
//
// The bot answers only when spoken to — /ask, an @mention, or a reply to
// something it said. Answering everything would add noise to the very group
// this is meant to calm down.

const BOT_USERNAME = $env.PULSE_BOT_USERNAME || '';

const update = $input.first().json;
const message = update.message || update.channel_post;
if (!message) return [];

const text = (message.text || message.caption || '').trim();
if (!text || message.from?.is_bot) return [];

const chatId = message.chat.id;
const channel = message.chat.title || `telegram:${chatId}`;
const author = [message.from?.first_name, message.from?.last_name]
  .filter(Boolean)
  .join(' ')
  .trim() || message.from?.username || 'Unknown';

function addressedQuestion() {
  const command = /^\/(ask|pulse)(?:@\S+)?\s+([\s\S]+)$/i.exec(text);
  if (command) return command[2].trim();
  if (/^\/(ask|pulse)(?:@\S+)?$/i.test(text)) return null;
  if (text.startsWith('/')) return null;
  if (BOT_USERNAME) {
    const mention = new RegExp(`@${BOT_USERNAME}\\b`, 'gi');
    if (mention.test(text)) {
      const stripped = text.replace(mention, ' ').replace(/\s+/g, ' ').trim();
      return stripped.length > 2 ? stripped : null;
    }
  }
  if (message.reply_to_message?.from?.is_bot) return text;
  if (message.chat.type === 'private') return text;
  return null;
}

const question = addressedQuestion();

return [
  {
    json: {
      chatId,
      replyToMessageId: message.message_id,
      isQuestion: question !== null,
      question: question || '',
      payload: {
        messages: [
          {
            externalId: `tg:${chatId}:${message.message_id}`,
            channel,
            authorName: author,
            authorId: message.from ? String(message.from.id) : undefined,
            content: text,
            messageDate: new Date(message.date * 1000).toISOString(),
            replyToExternalId: message.reply_to_message
              ? `tg:${chatId}:${message.reply_to_message.message_id}`
              : undefined,
          },
        ],
      },
    },
  },
];
